configuration.scripts:

document.addEventListener('DOMContentLoaded', function() {
  try {
    let element = document.getElementsByClassName("nav-right").item(0);
    if (element) {
      element.insertAdjacentHTML('afterbegin','<li class="m-r-10"><a href="#"><span id="nombreDocumento" class="badge badge-primary">projectName</span></a></li>');
    }

    const starttime=document.getElementsByClassName('nav-logo');
    if (starttime && starttime[0]) {
      starttime[0].remove();
    }

    const fondo=document.getElementsByClassName('badge badge-primary');
    if (fondo && fondo[1]) {
      fondo[1].removeAttribute('class');
    }

    let elementTypeRow = document.getElementsByClassName("container-fluid p-4 view dashboard-view");
    if (!elementTypeRow || !elementTypeRow[0]) return;
    elementTypeRow[0].setAttribute('id',"dashboardStadistic");

    let blockTest = elementTypeRow[0].children[0];
    if (blockTest && blockTest.children && blockTest.children.length >= 4) {
      blockTest.children.item(3).setAttribute('class','col-md-2');
      blockTest.children.item(2).setAttribute('class','col-md-2');
      blockTest.children.item(1).setAttribute('class','col-md-2');
      blockTest.children.item(0).setAttribute('class','col-md-2');
    }

    let elements=document.getElementsByTagName('H3');
    if (elements && elements.length >= 2) {
      let elementoFecha1= elements[0].innerHTML;
      let elementoFecha2= elements[1].innerHTML;
      let startExecution= new Date(elementoFecha1);
      let endExecution= new Date(elementoFecha2);
      let result= new Date(endExecution-startExecution);
      blockTest.insertAdjacentHTML('beforeend','<div class="col-md-2"> <div class="card"><div class="card-body"><p class="m-b-0">Execution Time</p><h3>'+result.getUTCHours().toString().padStart(2,0)+":"+result.getMinutes().toString().padStart(2,0)+":"+result.getUTCSeconds().toString().padStart(2,0)+'</h3></div></div></div>');
    }

    //bloque de codigo que agrega el registro total en la ultima fila de la tabla
    let tbodyElements=document.getElementsByClassName("col-lg-6 col-md-12 category-container")[0]
      .getElementsByClassName("table table-sm table-bordered")[0].getElementsByTagName("tbody")[0];

    let trElements=tbodyElements.getElementsByTagName("tr");
    let elementTotal;
    let elementList;
    for (let index = 0; index < trElements.length; index++) {
      elementList = trElements[index].getElementsByTagName("td")[0].textContent;
      if (elementList=="TOTALS") {
        elementTotal= trElements[index].cloneNode(true);
        trElements[index].remove();
      }
    }
    if (elementTotal) {
      tbodyElements.insertAdjacentHTML("beforeend",elementTotal.innerHTML);
    }

    //Bloque de codigo para sustitur los titulos Suite, Class, Events en el segmento estadistico del reporte
    let chartName=elementTypeRow[0].children[1].getElementsByTagName("h6");
    let charLeyend=elementTypeRow[0].children[1].getElementsByTagName("small");
    let sumaryScenario=elementTypeRow[0].children[0].getElementsByTagName("p");

    for (let index = 0; index < sumaryScenario.length; index++) {
      sumaryScenario[index].innerText=sumaryScenario[index].innerText.replace("Suite","Scenarios");
    }
    for (let index = 0; index < chartName.length; index++) {
      if (chartName[index].textContent=="Suite") {
        chartName[index].innerText="Scenarios";
      } else if (chartName[index].textContent=="Class") {
        chartName[index].innerText="Test Cases";
      } else {
        chartName[index].innerText="Test Steps";
      }
    }
    for (let index = 0; index < charLeyend.length; index++) {
      charLeyend[index].innerText=charLeyend[index].innerText.replace("class","test cases");
      charLeyend[index].innerText=charLeyend[index].innerText.replace("suite","scenarios");
      charLeyend[index].innerText=charLeyend[index].innerText.replace("events","test steps");
    }

    // ---------- Transform each scenario's step list into a 3-column table ----------
    function buildTableForBody(body) {
      try {
        if (!body || body.querySelector('table[data-ext-custom="logs"]')) return;

        const steps = Array.from(body.querySelectorAll(':scope > .step'));
        if (steps.length === 0) return;

        const table = document.createElement('table');
        table.className = 'table table-sm';
        table.setAttribute('data-ext-custom','logs');
        const thead = document.createElement('thead');
        thead.innerHTML = '<tr><th class="status-col">Status</th><th class="timestamp-col">Timestamp</th><th class="details-col">Details</th></tr>';
        const tbody = document.createElement('tbody');

        steps.forEach(function(step){
          const tr = document.createElement('tr');
          tr.className = 'event-row';

          // STATUS
          const tdStatus = document.createElement('td');
          let status = 'Info';
          if (step.classList.contains('pass-bg')) status = 'Pass';
          else if (step.classList.contains('fail-bg')) status = 'Fail';
          const badgeCls = status === 'Pass' ? 'badge log pass-bg' : (status === 'Fail' ? 'badge log fail-bg' : 'badge log');
          tdStatus.innerHTML = '<span class="'+badgeCls+'">'+status+'</span>';

          // TIMESTAMP (Spark may not expose per-step time; leave empty if not found)
          const tdTime = document.createElement('td');
          const timeEl = step.querySelector(':scope > small.time, :scope > span.time');
          tdTime.textContent = timeEl ? timeEl.textContent : '';

          // DETAILS
          const tdDetails = document.createElement('td');
          const detailsFrag = document.createElement('div');
          detailsFrag.innerHTML = step.innerHTML;
          tdDetails.appendChild(detailsFrag);

          tr.appendChild(tdStatus);
          tr.appendChild(tdTime);
          tr.appendChild(tdDetails);
          tbody.appendChild(tr);

          step.remove();
        });

        table.appendChild(thead);
        table.appendChild(tbody);
        body.appendChild(table);
      } catch (err) {
        console && console.warn && console.warn('Extent custom logs table error:', err);
      }
    }

    function transformAllVisibleScenarioBodies() {
      const scenarioBodies = document.querySelectorAll('.accordion .card .collapse.show .card-body, .accordion .card .collapse .card-body');
      scenarioBodies.forEach(buildTableForBody);
    }

    // Initial run
    transformAllVisibleScenarioBodies();

    // Observe for dynamic expands/loads
    const acc = document.querySelector('.accordion');
    if (acc) {
      const observer = new MutationObserver(function(mutations){
        let needsRun = false;
        mutations.forEach(function(m){
          if (m.type === 'childList' || (m.type === 'attributes' && (m.attributeName === 'class' || m.attributeName === 'style'))) {
            needsRun = true;
          }
        });
        if (needsRun) transformAllVisibleScenarioBodies();
      });
      observer.observe(acc, { subtree: true, childList: true, attributes: true });
    }
  } catch (e) {
    console && console.warn && console.warn('Extent custom script error:', e);
  }
});
